+        builder.endObject();
+        return builder;
+    }
+
+    @Override
+    public String getWriteableName() {
+        return NAME.getPreferredName();
+    }
+
+    @Override
+    public void writeTo(StreamOutput out) throws IOException {
+        out.writeString(featureName);
+        query.writeTo(out);
+    }
+
+    @Override
+    public String featureName() {
+        return featureName;
+    }
+
+    @Override
